def toposort(nodes: list[int], edges: list[tuple[int, int]]) -> list[int]:
    if not nodes:
        return []

    # Build adjacency set and in-degree count, handling duplicates
    adj = {n: set() for n in nodes}
    indegree = {n: 0 for n in nodes}

    for u, v in edges:
        if u == v:
            raise ValueError("Cycle detected (self-loop)")
        if v not in adj[u]:
            adj[u].add(v)
            indegree[v] += 1

    # Kahn's algorithm with min-heap behavior using sorted list
    # We need lexicographically smallest, so always pick the smallest available node
