    zero_indegree = [n for n in nodes if indegree[n] == 0]
    result = []

    while zero_indegree:
        # Pick the smallest node
        zero_indegree.sort()
        node = zero_indegree.pop(0)
        result.append(node)

        for neighbor in adj[node]:
